style.css:
@-moz-document domain("instagram.com") {
/* True Black Background */
    body, ._as9z, ._aa6e, ._aabd, ._a9-6, ._ab8w, 
    nav, main, article, section, div[role="main"] {
        background-color: #000000 !important;
    }

    /* Twitter-style White Borders/Boxes */
    article, ._ab8w._ab94._ab99._ab9f._ab9m._ab9p._abcm, 
    div._ac76, ._aa61 {
        border: 1px solid #2f3336 !important; /* Twitter dark border color */
        border-radius: 16px !important;
        margin-bottom: 12px !important;
        background-color: #000000 !important;
    }

    /* Feed Containment (Phone Layout Look) */
    main[role="main"] > section {
        max-width: 600px !important;
        margin: 0 auto !important;
        border-left: 1px solid #2f3336 !important;
        border-right: 1px solid #2f3336 !important;
    }

    /* Sidebar/Nav Tweaks */
    div[role="navigation"] {
        border-right: 1px solid #2f3336 !important;
    }

    /* Remove Default Overlays */
    ._aa4b, ._aa4c {
        background: transparent !important;
    }

    /* Text and Icon Contrast */
    h1, h2, span, div, a {
        color: #e7e9ea !important; /* Twitter text color */
    }

    /* Hide unnecessary desktop bloat to mimic mobile */
    div._as8h { 
        display: none !important; 
    }
}
